<script setup lang="ts">import{computed,ref,watch}from'vue';import{useRoute,useRouter}from'vue-router';import{componentGroups,componentPlan,components,type ComponentGroupId}from'../docs/catalog';import ComponentTile from'../components/ComponentTile.vue';const route=useRoute(),router=useRouter(),query=ref(''),mode=ref<'all'|'stable'|'planned'>('all'),group=ref<ComponentGroupId|'all'>((route.query.group as ComponentGroupId)||'all');watch(group,value=>void router.replace({query:value==='all'?{}:{group:value}}));const matches=(item:{name:string;title:string;description:string;group:ComponentGroupId})=>(item.name+item.title+item.description).toLowerCase().includes(query.value.toLowerCase())&&(group.value==='all'||item.group===group.value);const stableItems=computed(()=>components.filter(matches));const plannedItems=computed(()=>componentPlan.filter(matches));</script>
<template><article class="doc-section components-page"><div class="page-kicker">COMPONENT LANDSCAPE / 组件全景</div><div class="page-title-row"><div><h1>一个可持续扩展的<br>业务组件体系。</h1><p class="page-lead">当前稳定组件与规划能力统一放在八类版图中。稳定项可进入示例和 API，规划项展示边界与优先级。</p></div><div class="component-count"><strong>{{components.length}}</strong><span>STABLE</span><strong>{{componentPlan.length}}</strong><span>PLANNED</span></div></div><div class="component-toolbar"><label><span>搜索</span><input v-model="query" type="search" placeholder="组件名、中文名称或用途" /></label><div class="segment-filter" aria-label="组件状态"><button v-for="item in [{id:'all',label:'全部'},{id:'stable',label:'稳定'},{id:'planned',label:'规划'}]" :key="item.id" :class="{'is-active':mode===item.id}" @click="mode=item.id as any">{{item.label}}</button></div></div><div class="group-filter" aria-label="组件分类"><button :class="{'is-active':group==='all'}" @click="group='all'">全部</button><button v-for="item in componentGroups" :key="item.id" :class="{'is-active':group===item.id}" :style="{'--group-accent':item.accent}" @click="group=item.id">{{item.title}} <span>{{components.filter(c=>c.group===item.id).length+componentPlan.filter(c=>c.group===item.id).length}}</span></button></div><template v-for="item in componentGroups" :key="item.id"><section v-if="(group==='all'||group===item.id)&&((mode!=='planned'&&stableItems.some(c=>c.group===item.id))||(mode!=='stable'&&plannedItems.some(c=>c.group===item.id)))" class="component-group-section"><div class="component-group-head" :style="{'--group-accent':item.accent}"><span>{{item.english}}</span><h2>{{item.title}}</h2><p>{{item.description}}</p></div><div class="component-landscape"><ComponentTile v-for="component in mode!=='planned'?stableItems.filter(c=>c.group===item.id):[]" :key="component.name" :item="component"/><ComponentTile v-for="component in mode!=='stable'?plannedItems.filter(c=>c.group===item.id):[]" :key="component.name" :item="component" planned/></div></section></template><div v-if="!stableItems.length&&!plannedItems.length" class="empty-search" role="status"><strong>没有匹配的组件</strong><p>试试“日期”“表格”“反馈”或清除分类筛选。</p></div></article></template>
